import pandas as pd
import numpy as np
import math

def engineer_features(df):
    """
    Transform raw flat features into model-ready features, focusing on 
    the efficiency of order flow (Price Impact) and liquidity alignment.
    """
    df = df.copy()

    # 1. Price Impact Efficiency: How much price moves per unit of aggressive delta?
    # High positive = clean trend; High negative = absorption/reversal; Near zero = noise.
    df['price_momentum'] = df.groupby('market_slug')['binance_price'].diff().fillna(0)
    df['price_impact_efficiency'] = df['price_momentum'] / (df['mean_delta'].abs() + 1e-6)

    # 2. OBI-Delta Alignment: Does the order book support the aggressive flow?
    # Positive means the book and the flow are pushing in the same direction.
    df['obi_delta_alignment'] = df['mean_obi'] * np.sign(df['mean_delta'])

    # 3. Volatility-Normalized Delta: Is the flow significant relative to current volatility?
    df['vol_normalized_delta'] = df['mean_delta'] / (df['mean_volatility'] + 1e-6)

    # Drop metadata and target
    cols_to_drop = ['market_slug', 'timestamp', 'actual_outcome']
    X = df.drop(columns=[c for c in cols_to_drop if c in df.columns])

    # Final cleanup
    X = X.replace([np.inf, -np.inf], 0)
    X = X.fillna(0)

    return X

def get_hyperparams():
    """Return highly regularized hyperparameters to prioritize signal over noise."""
    return {
        'n_estimators': 1000,
        'max_depth': 2,
        'learning_rate': 0.01,
        'subsample': 0.6,
        'colsample_bytree': 0.6,
        'reg_alpha': 25.0,
        'reg_lambda': 25.0,
    }

def strategy_filter(prob_up, prob_down, cost_up, cost_down, features_row, seconds_remaining):
    """
    Decide whether to trade using "Regime-Adaptive Efficiency Gating (RAEG-2)".

    Logic:
    - Trend Regime: High efficiency + OBI alignment. Requires low EV threshold (0.025).
    - Absorption Regime: Negative efficiency (price moving against flow). Requires high EV threshold (0.05).
    - Neutral Regime: Low efficiency/No alignment. Requires moderate EV threshold (0.035).
    """
    ev_up = prob_up - cost_up
    ev_down = prob_down - cost_down

    if ev_up > ev_down:
        best_ev = ev_up
        side = 'Up'
    else:
        best_ev = ev_down
        side = 'Down'

    # Extract engineered features
    eff = features_row.get('price_impact_efficiency', 0.0)
    align = features_row.get('obi_delta_alignment', 0.0)
    
    # 1. Identify the Market Regime
    # Trend: Price is moving efficiently with the delta and the book supports it
    is_trend = eff > 0.05 and align > 0
    
    # Absorption: Price is moving against the delta (high delta, low/negative price move)
    is_absorption = eff < -0.05
    
    # 2. Set Regime-Specific Thresholds and Scaling
    if is_trend:
        # High conviction in momentum; lower threshold to capture moves early
        req_ev = 0.025
        multiplier = 1.0
    elif is_absorption:
        # High risk of 'traps'; require much higher edge to bet on a reversal
        req_ev = 0.05
        multiplier = 0.5
    else:
        # Noise/Neutral regime
        req_ev = 0.035
        multiplier = 0.7

    # 3. Time-Gating and Final Decision
    # Tighten requirements as the window closes to avoid late-stage volatility noise
    if seconds_remaining < 60:
        req_ev *= 1.2
        multiplier *= 0.8

    if best_ev > req_ev:
        # Scale bet size by the magnitude of the edge relative to a 5% target
        bet_fraction = multiplier * (best_ev / 0.05)
        return side, min(1.0, bet_fraction)

    return None, 0.0